47	#[typst_macros::time(name = "convert document")]
48	pub fn convert(
49	    typst_document: &PagedDocument,
50	    options: &PdfOptions,
51	    anchors: &[(Location, EcoString)],
52	    link_resolver: Option<Tracked<LateLinkResolver>>,
53	) -> SourceResult<Vec<u8>> {
54	    let settings = SerializeSettings {
55	        compress_content_streams: !options.pretty,
56	        no_device_cs: true,
57	        ascii_compatible: options.pretty,
58	        xmp_metadata: true,
59	        cmyk_profile: None,
60	        configuration: options.standards.config,
61	        enable_tagging: options.tagged,
62	        render_svg_glyph_fn: render_svg_glyph,
63	        pretty: options.pretty,
64	    };
65	
66	    let mut document = Document::new_with(settings);
67	    let page_index_converter = PageIndexConverter::new(typst_document, options);
68	    let named_destinations = collect_named_destinations(
69	        &mut document,
70	        typst_document,
71	        anchors,
72	        &page_index_converter,
73	    );
74	
75	    let tags = tags::init(typst_document, options)?;
76	
77	    let mut gc = GlobalContext::new(
78	        typst_document,
79	        options,
80	        link_resolver,
81	        named_destinations,
82	        page_index_converter,
83	        tags,
84	    );
85	
86	    convert_pages(&mut gc, &mut document)?;
87	    attach_files(&gc, &mut document)?;
88	    let (doc_lang, tree) = tags::resolve(&mut gc)?;
89	
90	    document.set_outline(build_outline(&gc));
91	    document.set_metadata(build_metadata(&gc, doc_lang));
92	    document.set_tag_tree(tree);
93	
94	    finish(document, gc, options.standards.config)
95	}
