97	fn convert_pages(gc: &mut GlobalContext, document: &mut Document) -> SourceResult<()> {
98	    for (i, typst_page) in gc.document.pages().iter().enumerate() {
99	        if gc.page_index_converter.pdf_page_index(i).is_none() {
100	            // Don't export this page.
101	            continue;
102	        }
103	
104	        // PDF 1.4 upwards to 1.7 specifies a minimum page size of 3x3 units.
105	        // PDF 2.0 doesn't define an explicit limit, but krilla and probably
106	        // some viewers won't handle pages that have zero sized pages.
107	        let mut settings = PageSettings::from_wh(
108	            (typst_page.frame.width() + typst_page.bleed.left + typst_page.bleed.right)
109	                .to_f32()
110	                .max(3.0),
111	            (typst_page.frame.height() + typst_page.bleed.top + typst_page.bleed.bottom)
112	                .to_f32()
113	                .max(3.0),
114	        )
115	        .expect_internal("invalid page size")
116	        .at(Span::detached())?;
117	
118	        if !typst_page.bleed.is_zero() {
119	            settings = settings.with_trim_box(Rect::from_ltrb(
120	                typst_page.bleed.left.to_f32(),
121	                typst_page.bleed.top.to_f32(),
122	                (typst_page.bleed.left + typst_page.frame.width()).to_f32(),
123	                (typst_page.bleed.top + typst_page.frame.height()).to_f32(),
124	            ));
125	        }
126	
127	        if let Some(label) = typst_page
128	            .numbering
129	            .as_ref()
130	            .and_then(|num| PageLabel::generate(num, typst_page.number))
131	            .or_else(|| {
132	                // When some pages were ignored from export, we show a page label with
133	                // the correct real (not logical) page number.
134	                // This is for consistency with normal output when pages have no numbering
135	                // and all are exported: the final PDF page numbers always correspond to
136	                // the real (not logical) page numbers. Here, the final PDF page number
137	                // will differ, but we can at least use labels to indicate what was
138	                // the corresponding real page number in the Typst document.
139	                gc.page_index_converter
140	                    .has_skipped_pages()
141	                    .then(|| PageLabel::arabic((i + 1) as u64))
142	            })
143	        {
144	            settings = settings.with_page_label(label);
145	        }
146	
147	        let mut page = document.start_page_with(settings);
148	        let mut surface = page.surface();
149	        let page_idx = gc.page_index_converter.pdf_page_index(i);
150	        let mut fc = FrameContext::new(
151	            page_idx,
152	            typst_page.frame.size() + typst_page.bleed.sum_by_axis(),
153	        );
154	
155	        tags::page(gc, &mut surface, |gc, surface| {
156	            handle_frame(
157	                &mut fc,
158	                &typst_page.frame,
159	                typst_page.bleed,
160	                typst_page.fill_or_transparent(),
161	                surface,
162	                gc,
163	            )
164	        })?;
165	
166	        surface.finish();
167	
168	        let link_annotations = fc.link_annotations.into_values().flatten();
169	        tags::add_link_annotations(gc, &mut page, link_annotations);
170	    }
171	
172	    Ok(())
173	}
